import {
  BaseGatewayAdapter,
  type GatewayMetadata,
  type GatewayField,
  type InitiateParams,
  type InitiateResult,
  type VerifyResult,
  type Credentials,
  type GatewayContext,
} from '../base';
import { gwJson } from '../kit/http';
import { timingSafeEqual } from '../../lib/hash';

const SLUG = "xendit";

export class XenditGateway extends BaseGatewayAdapter {
  metadata(): GatewayMetadata {
    return {
      name: "Xendit",
      slug: "xendit",
      version: '1.0.0',
      description: "Xendit payment gateway integration for Southeast Asia",
      author: 'EdgePay Gateway Plugin Suite (AGPLv3) — EdgePay port',
      type: 'gateway',
      supported_currencies: ["IDR", "PHP", "USD", "SGD"],
      capabilities: ["verification", "webhook"],
    };
  }

  fields(): GatewayField[] {
    return [
      { name: "api_key", label: "Secret API Key", type: "password" as const, required: true },
      { name: "callback_token", label: "Callback Verification Token", type: "password" as const, required: true },
    ];
  }

  async initiate(params: InitiateParams, credentials: Credentials, _ctx?: GatewayContext): Promise<InitiateResult> {
    const apiKey = String(credentials["api_key"] ?? '');
    const endpoint = "https://api.xendit.co/v2/invoices";
    const payload = { ["external_id"]: (params.trx_id ?? ''), ["amount"]: Number((params.amount ?? '')), ["payer_email"]: "customer@edgepay.test", ["description"]: `Payment ${String((params.trx_id ?? ''))}`, ["success_redirect_url"]: (params.redirect_url ?? ''), ["failure_redirect_url"]: (params.cancel_url ?? '') };
    const res = await gwJson({
      url: endpoint,
      method: 'POST',
      headers: { ["Content-Type"]: "application/json", ["Authorization"]: `Basic ${String(btoa(`${String(apiKey)}:`))}`, ["User-Agent"]: "EdgePay Gateway Client/1.0.0" },
      body: JSON.stringify(payload),
      timeoutMs: 15000,
    });
    if (res.status !== 200) throw new Error(`${SLUG}: HTTP ${res.status} ${res.text}`);
    if (res.data === null) throw new Error(`${SLUG}: invalid response`);
    const d = res.data as Record<string, unknown>;
    return {
          redirect_url: (String(((d) as Record<string, unknown>)["invoice_url"] ?? '') || undefined) as string | undefined,
          session_id: (String(((d) as Record<string, unknown>)["id"] ?? '') || undefined) as string | undefined,
        };
  }

  async verify(callbackData: Record<string, unknown>, credentials: Credentials, _ctx?: GatewayContext): Promise<VerifyResult> {
    const cb = callbackData as Record<string, unknown>;
    if (String(cb["id"] ?? '') === '') {
      return { success: false, gateway_trx_id: '', amount: null, status: 'failed' as const };
    }
    const apiKey = String(credentials["api_key"] ?? '');
    const endpoint = `https://api.xendit.co/v2/invoices/${String(encodeURIComponent(String(cb["id"] ?? cb["invoice_id"])))}`;
    const res = await gwJson({
      url: endpoint,
      method: 'GET',
      headers: { ["Authorization"]: `Basic ${String(btoa(`${String(apiKey)}:`))}`, ["User-Agent"]: "EdgePay Gateway Client/1.0.0" },
      timeoutMs: 10000,
    });
    if (res.data === null) {
          return { success: false, gateway_trx_id: '', amount: null, status: 'failed' as const };
        }
    const d = res.data as Record<string, unknown>;
    const ok = ["PAID", "SETTLED"].includes(String(((d) as Record<string, unknown>)["status"]));
    return {
          success: ok,
          gateway_trx_id: '',
          amount: null,
          status: (ok ? 'completed' : 'failed') as VerifyResult['status'],
        };
  }

  async verifyWebhook(input: { rawBody: string; headers: Record<string, string>; credentials: Credentials }): Promise<boolean> {
    const credentials = input.credentials;
    const expected = credentials["callback_token"] ?? '';
    if (expected === '') return false; // fail-closed: secret not configured
    const provided = input.headers["x-callback-token"] ?? '';
    const providedLower = input.headers["x-callback-token"] ?? '';
    return timingSafeEqual(expected, (provided || providedLower));
  }
}
